		// state first so that a pending 'jump' action isn't cancelled right
		// away by the wake-up event below.
		jumpingBefore := t.jumping
		if len(t.wait.pending) > 0 && !t.wait.blocked {
			pending := t.wait.pending
			t.wait.pending = nil
			if !doActions(pending) {
				continue
			}
		}

