		t.dispatchAsync()

		if t.pendingReqList {
			t.pendingReqList = false
			req(reqList)
		}

		t.mutex.Unlock() // Must be unlocked before touching reqBox

		if reload {
			t.eventBox.Set(EvtSearchNew, *reloadRequest)
		}
		for _, event := range events {
			t.reqBox.Set(event, nil)
		}
	}
	return nil
